-- verify_migrations.sql
-- Checks that EVERY migration in db/migrations has been applied: each migration's tables, columns, indexes,
-- views, functions and triggers must exist (and indexes that a migration drops must be gone).
--
--   psql "$DATABASE_URL" -f db/verify_migrations.sql
--   (or: ./scripts/verify-migrations.sh "$DATABASE_URL")
--
-- Output: one row per migration (OK / MISSING: ...) and a final one-line verdict. Read-only: it only creates a
-- session-local TEMP table. Keep this file in sync when you add a migration (tests/admin/migrations_verify.test.ts
-- fails if a migration has no checks here, or if any check fails on a fully migrated database).
\pset pager off
\pset null '-'

CREATE TEMP TABLE _mig_checks (mig text, what text, ok boolean);

SELECT mig AS migration,
       count(*) AS objects,
       count(*) FILTER (WHERE ok) AS present,
       CASE WHEN bool_and(ok) THEN 'OK'
            ELSE 'MISSING: ' || string_agg(what, ', ' ORDER BY what) FILTER (WHERE NOT ok) END AS status
FROM _mig_checks GROUP BY mig ORDER BY mig;

SELECT CASE WHEN bool_and(ok) THEN 'ALL ' || count(DISTINCT mig) || ' MIGRATIONS APPLIED'
            ELSE (SELECT count(DISTINCT mig) FROM _mig_checks WHERE NOT ok) || ' of ' || count(DISTINCT mig) || ' migrations incomplete - apply the ones marked MISSING above' END AS verdict
FROM _mig_checks;
